properties.query:
// CUSTOM - API keys listed or regenerated on a Microsoft Foundry or Azure OpenAI account
// ASSUMPTION: OperationNameValue strings match standard Microsoft.CognitiveServices ARM actions.
// Verify exact values in your tenant with:
//   AzureActivity | where ResourceProviderValue =~ "Microsoft.CognitiveServices" | distinct OperationNameValue
let approved_callers = dynamic(["platform-deployer-spn"]);
AzureActivity
| where TimeGenerated > ago(1h)
| where ResourceProviderValue =~ "Microsoft.CognitiveServices"
| where OperationNameValue in~ (
    "Microsoft.CognitiveServices/accounts/listKeys/action",
    "Microsoft.CognitiveServices/accounts/regenerateKey/action"
)
| where ActivityStatusValue =~ "Success"
| where Caller !in~ (approved_callers)
| project TimeGenerated, Caller, CallerIpAddress, OperationNameValue, ResourceGroup, _ResourceId, Properties

// CUSTOM - Cognitive Services account updated with public network access or local auth enabled
// ASSUMPTION: Properties_d / Properties JSON carries requestbody fields on ARM write operations
// when request body logging is present. Validate exact JSON path in your tenant first.
AzureActivity
| where TimeGenerated > ago(1h)
| where ResourceProviderValue =~ "Microsoft.CognitiveServices"
| where OperationNameValue =~ "Microsoft.CognitiveServices/accounts/write"
| where ActivityStatusValue =~ "Success"
| where Properties has_any ("\"publicNetworkAccess\":\"Enabled\"", "\"disableLocalAuth\":false")
| project TimeGenerated, Caller, CallerIpAddress, ResourceGroup, _ResourceId, Properties

// CUSTOM - Copilot settings or plugin lifecycle changes outside the approved admin list
// ASSUMPTION: RecordType or Operation values include CopilotSettings/Plugin actions.
// Verify exact strings in your tenant with:
//   CopilotActivity | where TimeGenerated > ago(30d) | distinct RecordType
let approved_admins = dynamic(["ai-admin@yourdomain.gov.au"]);
CopilotActivity
| where TimeGenerated > ago(1h)
| where RecordType != "CopilotInteraction"
| where ActorName !in~ (approved_admins)
| project TimeGenerated, RecordType, Workload, ActorName, ActorUserType, AppHost, SrcIpAddr, LLMEventData

// CUSTOM - Publishing credential (FTP or SCM/Kudu basic auth) login detected
// ASSUMPTION: AppServiceAuditLogs diagnostic setting is enabled on target Web Apps and Function Apps.
// Add known legacy deployment runner IPs to approved_ips while migrating them to Entra ID.
let approved_ips = dynamic([]);
AppServiceAuditLogs
| where TimeGenerated > ago(1h)
| where UserAddress !in (approved_ips)
| project TimeGenerated, App = _ResourceId, OperationName, Protocol, User, UserAddress

// CUSTOM - App Service publishing profile fetched or basic auth policy modified
// ASSUMPTION: AzureActivity is connected for subscriptions hosting App Service and Function Apps.
// Exclude approved CI/CD deployment service principals after baselining.
let approved_callers = dynamic([]);
AzureActivity
| where TimeGenerated > ago(1h)
| where ActivityStatusValue in ("Success", "Succeeded")
| where OperationNameValue has_any (
    "Microsoft.Web/sites/config/listpublishingcredentials/action",
    "Microsoft.Web/sites/basicPublishingCredentialsPolicies/write",
    "Microsoft.Web/sites/publishxml/action"
)
| where Caller !in~ (approved_callers)
| project TimeGenerated, Caller, CallerIpAddress, SubscriptionId, ResourceGroup,
          OperationNameValue, App = _ResourceId

// CUSTOM - Successful HTTP 200 responses on sensitive paths or suspected web shell probes
// ASSUMPTION: AppServiceHTTPLogs is in Analytics (or run in Data lake explorer as a scheduled hunt).
// Tune CsUriStem patterns for your application stack.
AppServiceHTTPLogs
| where TimeGenerated > ago(1h)
| where ScStatus == 200
| where CsUriStem has_any (
    "/.env", "/.git/", "/web.config", "/wp-admin", "/cmd.aspx", "/shell.aspx",
    "/api/vfs", "/api/command", "/api/zipdeploy"
)
| summarize Hits = count(), Paths = make_set(CsUriStem, 10), UserAgents = make_set(UserAgent, 5)
    by CIp, CsHost, _ResourceId
| order by Hits desc

// CUSTOM - Subscription or resource diagnostic setting deleted or modified
// ASSUMPTION: OperationNameValue uses uppercase ARM action strings in your tenant.
// Verify with: AzureActivity | where OperationNameValue has "DIAGNOSTICSETTINGS" | distinct OperationNameValue
let approved_automation = dynamic(["terraform-spn-object-id"]);
AzureActivity
| where TimeGenerated > ago(1h)
| where OperationNameValue in~ (
    "MICROSOFT.INSIGHTS/DIAGNOSTICSETTINGS/DELETE",
    "MICROSOFT.INSIGHTS/DIAGNOSTICSETTINGS/WRITE"
)
| where ActivityStatusValue in~ ("Success", "Succeeded")
| where Caller !in~ (approved_automation)
| project TimeGenerated, SubscriptionId, ResourceGroup, OperationNameValue, Caller, CallerIpAddress, ResourceId

// CUSTOM - High-privilege Azure RBAC role assignment created
// ASSUMPTION: Role definition GUIDs match built-in Owner (8e3af657-a8ff-443c-a75c-2fe8c4bcb635)
// and User Access Administrator (18d7d88d-d35e-4fb5-a5c3-7773c20a72d9).
// Confirm JSON shape of Properties.requestbody in one sample row before enabling.
let high_priv_roles = dynamic([
    "8e3af657-a8ff-443c-a75c-2fe8c4bcb635",
    "18d7d88d-d35e-4fb5-a5c3-7773c20a72d9"
]);
AzureActivity
| where TimeGenerated > ago(1h)
| where OperationNameValue =~ "MICROSOFT.AUTHORIZATION/ROLEASSIGNMENTS/WRITE"
| where ActivityStatusValue in~ ("Success", "Succeeded")
| extend RequestBody = parse_json(tostring(parse_json(Properties).requestbody))
| extend RoleDefId = tostring(RequestBody.Properties.RoleDefinitionId)
| extend PrincipalId = tostring(RequestBody.Properties.PrincipalId)
| where RoleDefId has_any (high_priv_roles)
| project TimeGenerated, SubscriptionId, Caller, CallerIpAddress, RoleDefId, PrincipalId, ResourceId

// CUSTOM - Storage account listKeys operation by caller outside known automation
// ASSUMPTION: OperationNameValue matches MICROSOFT.STORAGE/STORAGEACCOUNTS/LISTKEYS/ACTION.
// Check 30 days of history first to populate known_callers.
let known_callers = dynamic(["backup-automation-spn"]);
AzureActivity
| where TimeGenerated > ago(1h)
| where OperationNameValue =~ "MICROSOFT.STORAGE/STORAGEACCOUNTS/LISTKEYS/ACTION"
| where ActivityStatusValue in~ ("Success", "Succeeded")
| where Caller !in~ (known_callers)
| summarize Calls = count(), Accounts = make_set(ResourceId, 10) by Caller, CallerIpAddress, SubscriptionId

// CUSTOM - Privilege or role membership changes in Azure SQL audit logs
// ASSUMPTION: Default BATCH_COMPLETED_GROUP or DATABASE_ROLE_MEMBER_CHANGE_GROUP / DATABASE_PERMISSION_CHANGE_GROUP is enabled.
// Pin exact action_name_s values in your workspace before enabling.
let approved_principals = dynamic(["cicd-deploy-spn", "sql-admin@yourdomain.gov.au"]);
AzureDiagnostics
| where TimeGenerated > ago(1h)
| where Category == "SQLSecurityAuditEvents"
| where succeeded_s =~ "true"
| where action_name_s in ("ADD MEMBER", "GRANT", "ALTER ROLE", "CREATE USER", "ALTER USER")
    or statement_s has_any ("sp_addrolemember", "ALTER ROLE", "GRANT CONTROL", "GRANT IMPERSONATE", "db_owner")
| where server_principal_name_s !in~ (approved_principals)
| project TimeGenerated, LogicalServerName_s, database_name_s, server_principal_name_s,
          client_ip_s, action_name_s, statement_s

// CUSTOM - Subscription Secure Score drops by more than 10 percent compared to the prior 7-day peak
// ASSUMPTION: Continuous export for Secure score is enabled and writes to SecureScores.
// Check column names PercentageScore and SubscriptionId in a sample row before enabling.
let baseline = SecureScores
    | where TimeGenerated between (ago(7d) .. ago(1d))
    | summarize MaxScore7d = max(PercentageScore) by SubscriptionId;
SecureScores
| where TimeGenerated > ago(1d)
| summarize arg_max(TimeGenerated, PercentageScore, CurrentScore, MaxScore) by SubscriptionId
| join kind=inner baseline on SubscriptionId
| extend DropPercent = round((MaxScore7d - PercentageScore) * 100, 1)
| where DropPercent >= 10
| project TimeGenerated, SubscriptionId, MaxScore7d, PercentageScore, DropPercent

// CUSTOM - Key Vault purge or configuration change outside approved change identities
// ASSUMPTION: OperationName values match Key Vault audit log action names.
// Pin exact OperationName strings in your tenant with: AZKVAuditLogs | distinct OperationName
let approved_cicd = dynamic(["iac-pipeline-spn"]);
AZKVAuditLogs
| where TimeGenerated > ago(1h)
| where OperationName in ("SecretPurge", "KeyPurge", "CertificatePurge", "VaultPatch", "VaultPut", "KeyBackup", "SecretBackup")
| where ResultType =~ "Success" or HttpStatusCode in (200, 202)
| extend Caller = tostring(Identity)
| where not(Caller has_any (approved_cicd))
| project TimeGenerated, _ResourceId, OperationName, Caller, CallerIpAddress, ClientInfo

// CUSTOM - Copilot Studio agent or topic/component created or changed in production outside approved makers
// ASSUMPTION: replace prod_instances and approved_makers with watchlists for your tenant.
let prod_instances = dynamic(["https://your-prod-env.crm6.dynamics.com"]);
let approved_makers = dynamic(["agent-builder@yourdomain.gov.au"]);
DataverseActivity
| where TimeGenerated > ago(1h)
| where InstanceUrl in~ (prod_instances)
| where EntityName in ("bot", "botcomponent") and Message in ("Create", "Update", "Delete")
| where UserId !in~ (approved_makers)
| summarize Changes = count(), Tables = make_set(EntityName), Messages = make_set(Message)
            by UserId, ClientIp, InstanceUrl, EntityId

// CUSTOM - System Administrator security role assigned to a user in Dataverse
// ASSUMPTION: System Administrator roleid values are unique per Dataverse environment.
// Populate sysadmin_role_ids from a watchlist or query your environments first.
let sysadmin_role_ids = dynamic(["<System Administrator roleid, per environment>"]);
DataverseActivity
| where TimeGenerated > ago(1h)
| where Message == "Associate" and EntityName == "systemuser"
| mv-expand Field = Fields
| where tostring(Field.Name) == "role" and tostring(Field.Value) in~ (sysadmin_role_ids)
| project TimeGenerated, Actor = UserId, Action = "System Administrator role assigned", Environment = InstanceUrl, TargetUserId = tostring(EntityId)

// CUSTOM - Any new Microsoft Entra ID application mapping created in F&O outside an approved admin list
// ASSUMPTION: verify exact column names (TableName_s, Operation_s, UserId_s) in your FinanceOperationsActivity_CL schema first.
let approved_fo_admins = dynamic(["fo-admin@yourdomain.gov.au"]);
FinanceOperationsActivity_CL
| where TimeGenerated > ago(1h)
| where tostring(column_ifexists("TableName_s", "")) =~ "SysAADClientTable"
| where tostring(column_ifexists("Operation_s", "")) in~ ("Insert", "Update")
| extend Actor = tostring(column_ifexists("UserId_s", ""))
| where Actor !in~ (approved_fo_admins)
| project TimeGenerated, Actor, TableName = tostring(column_ifexists("TableName_s", "")), Operation = tostring(column_ifexists("Operation_s", ""))

// CUSTOM - Flow created or edited with consumer, file-share or raw HTTP connectors
// ASSUMPTION: FlowConnectorNames holds connector display names. Confirm with validation query 3 first.
let risky_connectors = dynamic(["Outlook.com", "Gmail", "Google Drive", "Dropbox", "HTTP", "FTP", "SFTP", "Telegram", "Slack"]);
PowerAutomateActivity
| where TimeGenerated > ago(1h)
| where EventOriginalType in ("CreateFlow", "EditFlow")
| where FlowConnectorNames has_any (risky_connectors)
| extend EnvironmentId = tostring(split(parse_url(FlowDetailsUrl).Path, "/")[2])
| project TimeGenerated, ActorName, EventOriginalType, FlowConnectorNames, FlowDetailsUrl, EnvironmentId, SrcIpAddr

// CUSTOM - Flow shared with a guest or someone outside your internal domains
// ASSUMPTION: replace internal_domains with your tenant's verified domains.
let internal_domains = dynamic(["yourdomain.gov.au"]);
PowerAutomateActivity
| where TimeGenerated > ago(1h)
| where isnotempty(RecipientUpn)
| extend RecipientDomain = tolower(tostring(split(RecipientUpn, "@")[1]))
| where RecipientUpn has "#EXT#" or RecipientDomain !in (internal_domains)
| extend Permission = case(SharingPermission == "3", "Owner", SharingPermission == "2", "Run-only", SharingPermission)
| project TimeGenerated, ActorName, EventOriginalType, RecipientUpn, Permission, FlowDetailsUrl

// CUSTOM - Hard threshold on downloads by one account in an hour, across all connected apps
// The built-in Unusual multiple file download activities uses a per-user learned baseline, so a
// slow-and-steady exfil under the baseline is invisible. This is the backstop.
// ASSUMPTION: Download ActionType values differ per app connector. Pin them first:
//   CloudAppEvents | where TimeGenerated > ago(7d) | where ActionType has_cs "ownload"
//   | summarize Rows = count() by Application, ActionType | order by Rows desc
let hourly_downloads = 300;
CloudAppEvents
| where TimeGenerated > ago(1h)
| where ActionType has_cs "ownload" or ActivityType has_cs "ownload"
| summarize Downloads = count(), Objects = dcount(ObjectId), Apps = make_set(Application, 5)
    by AccountObjectId, bin(TimeGenerated, 1h)
| where Downloads > hourly_downloads or Objects > 200
| project TimeGenerated, AccountObjectId, Downloads, Objects, Apps

// CUSTOM - Burst of delete events by one account in an hour, excluding Microsoft 365 workloads
// Rationale: the built-in Unusual file deletion activities covers M365 per-user anomalies, so
// this rule exists for connected non-Microsoft apps where the baseline coverage is thinner.
// ASSUMPTION: Delete ActionType values differ per app connector, and the excluded app list
// below is a placeholder. Pin exact Application strings with validation query 3 before enabling.
let hourly_deletes = 100;
let m365_apps = dynamic(["Microsoft SharePoint Online", "Microsoft OneDrive for Business", "Microsoft Office 365"]);
CloudAppEvents
| where TimeGenerated > ago(1h)
| where ActionType has_cs "elete" or ActivityType has_cs "elete"
| where Application !in (m365_apps)
| summarize Deletes = count(), Objects = dcount(ObjectId), Apps = make_set(Application, 5)
    by AccountObjectId, bin(TimeGenerated, 1h)
| where Deletes > hourly_deletes
| project TimeGenerated, AccountObjectId, Deletes, Objects, Apps

// CUSTOM - Download burst by a user flagged as external to the organisation
// The built-in detections baseline internal users. A guest with a modest export never
// generates an anomaly because there is no baseline to violate.
// ASSUMPTION: IsExternalUser is not populated on every app connector. Validate coverage:
//   CloudAppEvents | where TimeGenerated > ago(7d) | summarize Rows = count(), Ext = countif(IsExternalUser) by Application
let hourly_downloads = 100;
CloudAppEvents
| where TimeGenerated > ago(1h)
| where IsExternalUser == true
| where ActionType has_cs "ownload" or ActivityType has_cs "ownload"
| summarize Downloads = count(), Apps = make_set(Application, 5), FirstSeen = min(TimeGenerated)
    by AccountObjectId, AccountDisplayName
| where Downloads > hourly_downloads
| project FirstSeen, AccountObjectId, AccountDisplayName, Downloads, Apps

// CUSTOM - Spike in sensitivity label downgrades or removals by one user
// ASSUMPTION: Pin exact LabelEventType values in your tenant first with:
//   MicrosoftPurviewInformationProtection | where TimeGenerated > ago(30d) | distinct LabelEventType, Operation
// Replace watched_labels with the GUIDs of your Highly Confidential / Restricted labels.
let watched_labels = dynamic([
    "00000000-0000-0000-0000-000000000001",
    "00000000-0000-0000-0000-000000000002"
]);
MicrosoftPurviewInformationProtection
| where TimeGenerated > ago(1h)
| where LabelEventType has_any ("Downgrade", "Remove") or Operation has "Removed"
| where isnotempty(UserId)
| extend TouchedWatchedLabel = SensitivityLabelId in (watched_labels)
| summarize Events = count(), WatchedEvents = countif(TouchedWatchedLabel),
            Operations = make_set(Operation, 5), Workloads = make_set(Workload, 5),
            Apps = make_set(Application, 5)
    by UserId
| where Events >= 10 or WatchedEvents >= 3
| order by Events desc

// CUSTOM - Purview DLP policy or rule modified, disabled or removed outside approved admins
// ASSUMPTION: Confirm exact Operation strings emitted by your tenant with:
//   OfficeActivity | where TimeGenerated > ago(30d) | where Operation has "DlpCompliance" | distinct Operation
let approved_admins = dynamic(["compliance-admin@yourdomain.gov.au"]);
OfficeActivity
| where TimeGenerated > ago(1h)
| where Operation in~ (
    "Remove-DlpCompliancePolicy",
    "Remove-DlpComplianceRule",
    "Set-DlpCompliancePolicy",
    "Set-DlpComplianceRule",
    "Disable-DlpComplianceRule"
)
| where UserId !in~ (approved_admins)
| project TimeGenerated, Operation, UserId, ClientIP, OfficeWorkload, Parameters

// CUSTOM - Azure DevOps audit stream modified/deleted or Log Audit Events disabled
// ASSUMPTION: OperationName values match Azure DevOps Auditing event names for AuditLog and Policy.
// Confirm exact OperationName strings in your tenant with:
//   AzureDevOpsAuditing | where TimeGenerated > ago(30d) | where Area in ("AuditLog", "Policy") | distinct OperationName
AzureDevOpsAuditing
| where TimeGenerated > ago(1h)
| where OperationName in~ (
    "AuditLog.DeleteStream",
    "AuditLog.UpdateStream",
    "AuditLog.DisableStream",
    "Policy.PolicyValueUpdated"
)
| where OperationName !~ "Policy.PolicyValueUpdated" or Details has_any ("LogAuditEvents", "Audit")
| project TimeGenerated, ActorUPN, ActorDisplayName, IpAddress, UserAgent, Area, OperationName, Details, Data

// CUSTOM - Personal Access Token created with broad scope or by non-standard actor
// ASSUMPTION: OperationName for PAT creation is "Token.PatCreateEvent" and Scopes/Data carries
// token scope metadata (verify exact column contents on a test PAT creation event first).
AzureDevOpsAuditing
| where TimeGenerated > ago(1h)
| where OperationName =~ "Token.PatCreateEvent"
| where Scopes has_any ("app_token", "vso.full_access") or Details has_any ("All accessible organizations", "Full access")
| project TimeGenerated, ActorUPN, ActorDisplayName, IpAddress, UserAgent, AuthenticationMechanism, Scopes, Details, Data

// CUSTOM - Service connection permissions broadened or modified unexpectedly
// ASSUMPTION: Area == "Library" and OperationName matches ServiceEndpoint / PipelinePermission events.
// Validate exact OperationName strings in your tenant with:
//   AzureDevOpsAuditing | where TimeGenerated > ago(30d) | where Area == "Library" | distinct OperationName
let approved_admins = dynamic(["devops-admin@yourdomain.gov.au"]);
AzureDevOpsAuditing
| where TimeGenerated > ago(1h)
| where Area =~ "Library"
| where OperationName has_any ("ServiceEndpoint", "PipelinePermission")
| where Details has_any ("all pipelines", "Authorize", "Modified", "Created")
| where ActorUPN !in~ (approved_admins)
| project TimeGenerated, ProjectName, ActorUPN, IpAddress, AuthenticationMechanism, OperationName, Details, Data

// CUSTOM - Repository visibility changed to public
// ASSUMPTION: GitHubAuditData exposes Action, Actor, Repo, Org and ActorIp.
// Confirm exact column names and Action values on your workspace:
//   GitHubAuditData | where TimeGenerated > ago(30d) | where Action has "repo.access" | take 5
GitHubAuditData
| where TimeGenerated > ago(1h)
| where Action =~ "repo.access"
| where tostring(Visibility) =~ "public" or tostring(RawData) has "\"visibility\":\"public\""
| project TimeGenerated, Actor, ActorIp, Org, Repo, Action

// CUSTOM - Secret scanning push protection bypass or secret alert resolution
// ASSUMPTION: GitHub audit actions match GitHub Enterprise Cloud naming for secret scanning.
// Verify exact Action values in your tenant before enabling.
GitHubAuditData
| where TimeGenerated > ago(1h)
| where Action in~ (
    "secret_scanning_push_protection.bypass",
    "secret_scanning_alert.resolve",
    "repo.secret_scanning_push_protection_disable",
    "org.secret_scanning_push_protection_disable"
)
| project TimeGenerated, Actor, ActorIp, Org, Repo, Action

// CUSTOM - Post-delivery action on delivered mail did not succeed
// ASSUMPTION: ActionResult values are not documented. Run the summary query first and pin them:
//   EmailPostDeliveryEvents | distinct ActionType, ActionResult
EmailPostDeliveryEvents
| where TimeGenerated > ago(1h)
| where ActionType in ("Phish ZAP", "Malware ZAP", "Manual remediation")
| where tostring(ActionResult) !~ "Success"
| project TimeGenerated, NetworkMessageId, RecipientEmailAddress, SenderFromAddress,
          ActionType, ActionTrigger, ActionResult, DeliveryLocation, ThreatTypes

// CUSTOM - New or modified inbox rule, or Set-Mailbox, forwarding outside the org.
// Catches single-mailbox external forwarding that the OOB shared-destination rule
// only catches when two or more mailboxes point at the same destination.
// ASSUMPTION: ForwardTo, RedirectTo and ForwardingSmtpAddress are the parameter
// names in OfficeActivity Parameters. They match the OOB Office_MailForwarding rule.
let internal_domains = dynamic(["yourdomain.gov.au"]);
OfficeActivity
| where TimeGenerated > ago(1h)
| where OfficeWorkload =~ "Exchange"
| where Operation in~ ("New-InboxRule", "Set-InboxRule", "Set-Mailbox")
| mv-expand P = todynamic(Parameters)
| where tostring(P.Name) in~ ("ForwardTo", "RedirectTo", "ForwardingSmtpAddress")
| extend Destination = tostring(P.Value)
| mv-expand split(Destination, ";")
| extend DestDomain = tolower(tostring(split(tostring(Destination), "@")[1]))
| where isnotempty(DestDomain) and DestDomain !in (internal_domains)
| project TimeGenerated, UserId, ClientIP, Operation, Destination = tostring(Destination)

// CUSTOM - Mail access via a client protocol or IP unseen for that mailbox in 14 days.
// Attackers access mail through IMAP, EWS or ActiveSync rather than Outlook,
// so a new client on a busy mailbox is a strong compromise signal.
// ASSUMPTION: ClientInfoString and Client_IPAddress carry protocol and IP for
// MailItemsAccessed, matching the OOB MailItemsAccessedTimeSeries rule fields.
// ASSUMPTION: New joiners have no baseline, so the volume floor matters.
let lookback = 14d;
let floor_events = 10;
let baseline =
  OfficeActivity
  | where TimeGenerated between (ago(lookback) .. ago(1d))
  | where Operation =~ "MailItemsAccessed"
  | summarize by MailboxOwnerUPN, ClientInfoString;
OfficeActivity
| where TimeGenerated > ago(1d)
| where Operation =~ "MailItemsAccessed"
| summarize Events = count(), SampleIP = make_set(Client_IPAddress, 5),
            FirstSeen = min(TimeGenerated), Latest = max(TimeGenerated)
            by MailboxOwnerUPN, ClientInfoString
| where Events >= floor_events
| join kind=leftanti baseline on MailboxOwnerUPN, ClientInfoString
| project MailboxOwnerUPN, ClientInfoString, Events, SampleIP, FirstSeen, Latest

// CUSTOM - Add-MailboxPermission granting FullAccess. The OOB rare operations rule
// fires on every Add-MailboxPermission, so this filters to FullAccess grants by
// humans. Microsoft service accounts perform documented maintenance with this
// cmdlet and are excluded.
// ASSUMPTION: The system account strings match the exclusions Microsoft uses in
// the OOB RareOfficeOperations rule and the documented system account notes.
let system_noise = dynamic(["NT AUTHORITY", "NT SERVICE", "devilfish-applicationaccount",
                            "apcprd03.prod.outlook.com"]);
// ASSUMPTION: the target mailbox identity for Add-MailboxPermission is carried in
// OfficeObjectId, matching how the OOB rules use it for Exchange events. The table
// reference describes OfficeObjectId as SharePoint oriented, so check one record
// in your tenant and switch to the right column if needed.
OfficeActivity
| where TimeGenerated > ago(24h)
| where Operation =~ "Add-MailboxPermission"
| where Parameters has "FullAccess"
| where UserId !has_any (system_noise)
| extend TargetMailbox = tostring(split(tostring(OfficeObjectId), "/")[0])
| project TimeGenerated, UserId, ClientIP, Parameters, TargetMailbox

// CUSTOM - Any transport rule create or modify, not just redirects.
// The OOB rule only fires when BlindCopyTo or RedirectMessageTo is set. This
// catches quiet rule edits, so keep an approved-admin list to cut noise.
// Run daily over a 24h lookback to stay out of the OOB rule's way.
let approved_admins = dynamic(["mail-admin@yourdomain.gov.au"]);
OfficeActivity
| where TimeGenerated > ago(24h)
| where OfficeWorkload =~ "Exchange"
| where Operation in~ ("New-TransportRule", "Set-TransportRule")
| where UserId !in~ (approved_admins)
| project TimeGenerated, UserId, ClientIP, Operation, OfficeObjectId, Parameters
| order by TimeGenerated desc

// CUSTOM - Someone turned off unified audit logging for the tenant.
// The OOB "Exchange AuditLog Disabled" rule only watches AdminAuditLogEnabled.
// This watches the switch that kills every Microsoft 365 feed into Sentinel.
// ASSUMPTION: the Set-AdminAuditLogConfig record still reaches Sentinel after
// ingestion is disabled. Microsoft states that audit status changes are audited
// and searchable (see audit-log-enable-disable), but treat total silence in
// OfficeActivity as the stronger signal either way.
OfficeActivity
| where TimeGenerated > ago(24h)
| where Operation =~ "Set-AdminAuditLogConfig"
| mv-expand P = todynamic(Parameters)
| where tostring(P.Name) =~ "UnifiedAuditLogIngestionEnabled"
| where tostring(P.Value) =~ "False"
| project TimeGenerated, UserId, ClientIP, Operation, ParameterValue = tostring(P.Value)

// CUSTOM - A workload or record type that has not been seen for 30 days starts
// sending data. Legitimate causes: a new connector, a licence change, a service
// that just started auditing. Worth a look either way.
// Run daily with a 1d lookback.
let lookback = 30d;
let known = OfficeActivity
 | where TimeGenerated between (ago(lookback) .. ago(1d))
 | summarize by OfficeWorkload, RecordType;
OfficeActivity
| where TimeGenerated > ago(1d)
| summarize Rows = count(), Actors = dcount(UserId) by OfficeWorkload, RecordType
| join kind=leftanti known on OfficeWorkload, RecordType
| project OfficeWorkload, RecordType, Rows, Actors

// CUSTOM - Anonymous link activity on sites you care about
// Feed the list from a watchlist of sensitive site URLs.
let sensitive_sites = dynamic(["https://yourtenant.sharepoint.com/sites/finance",
                               "https://yourtenant.sharepoint.com/sites/board"]);
OfficeActivity
| where TimeGenerated > ago(1h)
| where Operation in ("AnonymousLinkCreated", "AnonymousLinkUsed", "AnonymousLinkUpdated")
| where tostring(Site_Url) in (sensitive_sites)
| project TimeGenerated, Operation, UserId, Site_Url, SourceFileName, ClientIP

// CUSTOM - File or folder shared to a consumer mail domain
let personal_domains = dynamic(["gmail.com", "outlook.com", "hotmail.com", "yahoo.com",
                                "icloud.com", "proton.me", "bigpond.com"]);
OfficeActivity
| where TimeGenerated > ago(1h)
| where Operation in ("SharingSet", "SharingInvitationCreated")
| extend TargetDomain = tolower(tostring(split(TargetUserOrGroupName, "@")[1]))
| where TargetDomain in (personal_domains)
| project TimeGenerated, Operation, UserId, TargetUserOrGroupName, SharingType,
          SourceFileName, Site_Url

// CUSTOM - App or bot installed or published, with an approved list
// ASSUMPTION: Your approved app list. Feed it from a watchlist.
let approved_apps = dynamic(["Microsoft Planner", "Microsoft Lists", "Approval"]);
let app_ops = dynamic(["AppInstalled", "AppPublishedToCatalog", "BotAddedToTeam", "ConnectorAdded"]);
OfficeActivity
| where TimeGenerated > ago(1h)
| where OfficeWorkload =~ "MicrosoftTeams"
| where Operation in (app_ops)
| extend Target = coalesce(tostring(ItemName), tostring(AddonName), "")
| where Target !in~ (approved_apps)
| project TimeGenerated, Operation, UserId, Target, TeamName, ClientIP

// CUSTOM - Teams tenant or admin settings that change who can get in
// ASSUMPTION: The setting name is in the Item column for TeamsTenantSettingChanged.
// Pin the values your tenant emits before narrowing the filter:
//   OfficeActivity | where Operation in ("TeamsTenantSettingChanged", "TeamsAdminAction")
//   | distinct Operation, Item, Parameters
OfficeActivity
| where TimeGenerated > ago(1h)
| where OfficeWorkload =~ "MicrosoftTeams"
| where Operation in ("TeamsTenantSettingChanged", "TeamsAdminAction")
| where tostring(Item) has_any ("guest", "external", "federation", "sharing", "access")
    or tostring(Parameters) has_any ("Guest", "Federation", "AllowGuest")
| project TimeGenerated, Operation, UserId, Item, Parameters, ClientIP

// CUSTOM - Office app spawned a script interpreter, then the device made an outbound connection
// ASSUMPTION: DeviceProcessEvents and DeviceNetworkEvents are streamed to this workspace.
// Without streaming, port this query to a Defender XDR custom detection instead.
let office_apps = dynamic(["winword.exe", "excel.exe", "powerpnt.exe", "outlook.exe", "msaccess.exe"]);
let interpreters = dynamic(["powershell.exe", "cmd.exe", "wscript.exe", "cscript.exe", "mshta.exe"]);
let spawns = DeviceProcessEvents
| where TimeGenerated > ago(2h)
| where InitiatingProcessFileName in~ (office_apps)
| where FileName in~ (interpreters)
| project DeviceId, FirstSeen = TimeGenerated, Parent = InitiatingProcessFileName,
    Interpreter = FileName, Cmd = ProcessCommandLine;
DeviceNetworkEvents
| where TimeGenerated > ago(1h)
| where RemoteIPType == "Public"
| join kind=inner spawns on DeviceId
| where TimeGenerated > FirstSeen
| summarize Connections = count(), DestIPs = make_set(RemoteIP, 5), Ports = make_set(RemotePort, 5)
    by DeviceId, Parent, Interpreter, Cmd
| project-away DeviceId1

// CUSTOM - Process SHA1 matching a watchlist fed from your own threat intel
// This is the case that justifies streaming: joining MDE data with non-Microsoft data in Sentinel.
// ASSUMPTION: a watchlist alias "BlockedHashes" exists, with the hash in the SearchKey column.
let blocked = _GetWatchlist("BlockedHashes")
| project SHA1 = tolower(tostring(SearchKey));
DeviceProcessEvents
| where TimeGenerated > ago(1h)
| where tolower(SHA1) in ((blocked))
| project TimeGenerated, DeviceName, AccountName, FileName, FolderPath,
    ProcessCommandLine, InitiatingProcessFileName, SHA1

// CUSTOM - Wipe, Retire or Delete device action
// ASSUMPTION: OperationName matches the friendly action names shown in the Intune admin centre,
// such as Wipe, Retire and Delete. Pin the exact strings with validation query 2 before enabling.
// ASSUMPTION: CorrelationId is unique per audit event. The summarize deduplicates the export's known duplicate rows.
IntuneAuditLogs
| where TimeGenerated > ago(1h)
| where OperationName has_any ("wipe", "retire", "delete")
| summarize FirstSeen = min(TimeGenerated), Sample = any(Properties)
            by OperationName, Actor = Identity, CorrelationId
| project FirstSeen, OperationName, Actor, CorrelationId, Sample

// CUSTOM - Many wipe, retire or delete actions by one actor in an hour
// Tenant limits are 500 Wipe and 1,000 Retire or Delete actions per day, so bursts can be a
// legitimate device refresh. Alert above your baseline and always check the actor's sign-ins.
// ASSUMPTION: same OperationName values as C1.
IntuneAuditLogs
| where TimeGenerated > ago(1h)
| where OperationName has_any ("wipe", "retire", "delete")
| summarize Events = dcount(CorrelationId), FirstSeen = min(TimeGenerated)
            by Actor = Identity, bin(TimeGenerated, 1h)
| where Events >= 10
| project FirstSeen, Actor, Events

// CUSTOM - Platform script or remediation created, changed or assigned
// ASSUMPTION: script operations carry Script in OperationName. Pin the exact values with
// validation query 2 and replace the has filter with your OperationName list.
IntuneAuditLogs
| where TimeGenerated > ago(24h)
| where OperationName has "script"
| summarize FirstSeen = min(TimeGenerated), Sample = any(Properties)
            by OperationName, Actor = Identity, CorrelationId
| project FirstSeen, OperationName, Actor, Sample

// CUSTOM - Compliance policy change outside the approved admin list
let approved_admins = dynamic(["intune-admin@yourdomain.gov.au"]);
// ASSUMPTION: the audit schema lists Compliance as category value 2, but your table may store
// the name or the number. Check both forms with validation query 2.
IntuneAuditLogs
| where TimeGenerated > ago(24h)
| where Category =~ "compliance" or Category == "2"
| where Identity !in~ (approved_admins)
| summarize FirstSeen = min(TimeGenerated), Sample = any(Properties)
            by OperationName, Actor = Identity, CorrelationId
| project FirstSeen, OperationName, Actor, Sample

// CUSTOM - AppLocker block events where the blocked file sits in a user-writable path
// ASSUMPTION: your event set includes 8004 and 8006. Minimal and Common both do.
// ASSUMPTION: AppLocker events map the file path into FilePath. Check one real event first.
SecurityEvent
| where TimeGenerated > ago(1h)
| where EventID in (8004, 8006)
| where FilePath has_any (":\\Users\\", ":\\ProgramData\\", ":\\Windows\\Temp\\")
| project TimeGenerated, Computer, SubjectUserName, EventID, FilePath

// CUSTOM - RDP logon from an IP the user hasn't used in the last 14 days
// Run daily over a 1-day lookback.
// ASSUMPTION: LogonType 10 is RemoteInteractive in your data. LogonType is an int column.
let lookback = 14d;
let history = SecurityEvent
| where TimeGenerated > ago(lookback) and TimeGenerated < ago(1d)
| where EventID == 4624 and LogonType == 10
| summarize by TargetUserName, IpAddress;
SecurityEvent
| where TimeGenerated > ago(1d)
| where EventID == 4624 and LogonType == 10
| join kind=leftanti history on TargetUserName, IpAddress
| project TimeGenerated, Computer, TargetUserName, IpAddress

// CUSTOM - directory replication from a non domain controller account, filtered to the replication rights GUIDs
SecurityEvent
| where TimeGenerated > ago(1h)
| where EventID == 4662
| where ObjectServer =~ "DS"
// ASSUMPTION: the replication access rights are listed in the Properties field of 4662 events.
// The GUIDs below are the DS-Replication-Get-Changes rights. Confirm they appear in your events with:
//   SecurityEvent | where EventID == 4662 | take 5 | project Properties
| where Properties has_any ("1131f6aa-9c07-11d1-f79f-00c04fc2dcd2",
                            "1131f6ad-9c07-11d1-f79f-00c04fc2dcd2")
// Domain controllers authenticate as computer accounts ending in $. Exclude them.
| where SubjectUserName !endswith "$" and AccountType != "Machine"
| project TimeGenerated, Computer, SubjectUserName, SubjectDomainName, ObjectName, IpAddress, Process

// CUSTOM - burst of RC4 encrypted Kerberos service tickets per requesting account
SecurityEvent
| where TimeGenerated > ago(1h)
| where EventID == 4769
// ASSUMPTION: the ticket encryption type is inside EventData, with RC4 encoded as 0x17,
// and the requested SPN is in the same EventData. Confirm the rendering first:
//   SecurityEvent | where EventID == 4769 | take 5 | project EventData
| where EventData has "0x17"
| summarize Tickets = count() by SubjectUserName, IpAddress
| where Tickets >= 10
| project SubjectUserName, IpAddress, Tickets

// CUSTOM - account with no logon history for 30 days added to a Tier 0 group
let tier0_groups = dynamic(["Domain Admins", "Enterprise Admins", "Schema Admins", "Account Operators", "Administrators"]);
let recent_logons = SecurityEvent
    | where TimeGenerated > ago(30d)
    | where EventID == 4624
    | summarize LastLogon = max(TimeGenerated) by TargetUserName;
SecurityEvent
| where TimeGenerated > ago(24h)
| where EventID in (4728, 4732, 4756)
// ASSUMPTION: for these events the group is in TargetAccount and the added member in MemberName.
// Validate with: SecurityEvent | where EventID == 4728 | take 5
| where TargetAccount has_any (tier0_groups)
| extend AddedAccount = tostring(split(MemberName, "\\")[-1])
| join kind=leftouter recent_logons on $left.AddedAccount == $right.TargetUserName
| where isempty(LastLogon) or LastLogon < ago(30d)
| project TimeGenerated, Computer, Actor = SubjectUserName, AddedAccount, TargetAccount, LastLogon

// CUSTOM - interactive or RDP logon by the AD FS service account
// ASSUMPTION: replace the list with your AD FS service account names.
// A gMSA renders with a trailing dollar, for example ADFSSVC$.
let adfs_service_accounts = dynamic(["adfssvc$", "ADFS-SVC$"]);
SecurityEvent
| where TimeGenerated > ago(1h)
| where EventID == 4624
| where LogonType in (2, 10)
| where TargetUserName has_any (adfs_service_accounts)
| project TimeGenerated, Computer, TargetUserName, LogonType, IpAddress, Process

// CUSTOM - directory service change touching the AD FS configuration container
// ASSUMPTION: AD FS configuration objects carry "ADFS" in the ObjectName of 5136 events.
// Confirm with: SecurityEvent | where EventID == 5136 | take 20 | project ObjectName, OperationType
SecurityEvent
| where TimeGenerated > ago(24h)
| where EventID == 5136
| where ObjectName has_cs "ADFS"
| project TimeGenerated, Computer, SubjectUserName, ObjectName, OperationType, ObjectDN

// CUSTOM - account with no recent logons added to a privileged group
// ASSUMPTION: group membership changes surface with an ActionType containing "Group".
// Pin the exact values first: IdentityDirectoryEvents | where TimeGenerated > ago(7d) | distinct ActionType
let tier0_groups = dynamic(["Domain Admins", "Enterprise Admins", "Schema Admins", "Account Operators", "Administrators"]);
IdentityDirectoryEvents
| where TimeGenerated > ago(1h)
| where ActionType has_cs "Group"
| extend GroupName = tostring(parse_json(AdditionalFields).TARGET_OBJECT_ORIGINAL_NAME)
// ASSUMPTION: the added account name and the group are in AdditionalFields for this ActionType.
// Confirm the property names from one alert row before you enable this rule.
| extend AddedAccount = tostring(parse_json(AdditionalFields).TARGET_ACCOUNT_NAME)
| where GroupName in~ (tier0_groups) and isnotempty(AddedAccount)
| join kind=leftouter (
    IdentityLogonEvents
    | where TimeGenerated > ago(30d)
    | extend AccountName = tolower(AccountName)
    | summarize LastLogon = max(TimeGenerated) by AccountName
) on $left.AddedAccount == $right.AccountName
| where isempty(LastLogon) or LastLogon < ago(30d)
| project TimeGenerated, AddedAccount, GroupName, Actor = AccountName, ActorUpn = AccountUpn, LastLogon

// CUSTOM - First-seen destination FQDN in the tenant, 14 day baseline
// Catches freshly spun-up C2 or exfil infrastructure the TI rules have never seen.
// ASSUMPTION: DestinationFqdn is populated for internet traffic. Raw IP destinations return
// an empty FQDN, so pair this with a first-seen DestinationIp rule if you care about IP-only traffic.
let lookback = 14d;
let known =
    NetworkAccessTraffic
    | where TimeGenerated between (ago(lookback) .. ago(1h))
    | where isnotempty(DestinationFqdn)
    | summarize by DestinationFqdn;
NetworkAccessTraffic
| where TimeGenerated > ago(1h)
| where isnotempty(DestinationFqdn)
| where DestinationFqdn !in (known)
| summarize FirstSeen = min(TimeGenerated), Users = dcount(UserPrincipalName),
            Samples = make_set(strcat(SourceIp, ' ', Action), 5)
    by DestinationFqdn
| project DestinationFqdn, FirstSeen, Users, Samples

// CUSTOM - Large outbound volume from one user to one destination in an hour
// Exfiltration over the SWG path that policy allowed. MDCA only sees SaaS app activity,
// so this catches uploads to destinations no app connector covers.
// ASSUMPTION: The threshold. Start high, then tune against validation query 5 volume data.
let threshold_bytes = 2 * 1024 * 1024 * 1024; // 2 GB
NetworkAccessTraffic
| where TimeGenerated > ago(1h)
| where isnotempty(DestinationFqdn)
| summarize SentBytes = sum(SentBytes), Transactions = count() by UserPrincipalName, DestinationFqdn, bin(TimeGenerated, 1h)
| where SentBytes > threshold_bytes
| project TimeGenerated, UserPrincipalName, DestinationFqdn, SentBytes, Transactions

// CUSTOM - Burst of Kerberos pre-auth failures from one principal or IP in 10 minutes
// Password spraying against on-prem apps exposed through the Private Access ZTNA path.
// ASSUMPTION: Kerberos columns only populate for private access flows that use Kerberos SSO.
// Verify with: NetworkAccessTraffic | where TimeGenerated > ago(1d) | where isnotempty(KerberosErrorCodeName) | take 10
NetworkAccessTraffic
| where TimeGenerated > ago(10m)
| where KerberosErrorCodeName == "KDC_ERR_PREAUTH_FAILED"
| summarize Failures = count(), Targets = dcount(ServicePrincipalName) by UserPrincipalName, SourceIp, bin(TimeGenerated, 10m)
| where Failures > 10 or Targets > 5
| project TimeGenerated, UserPrincipalName, SourceIp, Failures, Targets

// CUSTOM - MCP traffic to a destination URL never seen in the last 14 days
// The MCP Servers Dashboard workbook shows current MCP servers, but the solution ships no
// detection for a NEW one. Needs the NetworkAccessGenerativeAIInsights diagnostic category
// and TLS inspection, or the Copilot Studio integration path.
// ASSUMPTION: Activity is "MCP" for MCP operations and "Prompt" for prompt events, per the
// Generative AI Insights docs. Pin values first:
// NetworkAccessGenerativeAIInsights | where TimeGenerated > ago(1d) | summarize Rows = count() by Activity, SubActivity
let lookback = 14d;
let known =
    NetworkAccessGenerativeAIInsights
    | where TimeGenerated between (ago(lookback) .. ago(1h))
    | where Activity == "MCP"
    | summarize by DestinationUrl;
NetworkAccessGenerativeAIInsights
| where TimeGenerated > ago(1h)
| where Activity == "MCP"
| where DestinationUrl !in (known)
| summarize FirstSeen = min(TimeGenerated), Users = dcount(UserPrincipalName),
            Primitives = make_set(McpPrimitiveNames, 10) by DestinationUrl
| project DestinationUrl, FirstSeen, Users, Primitives

// CUSTOM - OAuth consent or grant by someone outside the approved admin list
// The extraction pattern mirrors Microsoft's own consent rules: user UPN if present, app name otherwise.
// ASSUMPTION: OperationName values. Pin exact strings first:
//   AuditLogs | where TimeGenerated > ago(30d)
//   | where OperationName has "consent" or OperationName has "OAuth2" or OperationName has "service principal"
//   | distinct OperationName
let approved_admins = dynamic(["id-admin@yourdomain.gov.au"]);
AuditLogs
| where TimeGenerated > ago(1d)
| where OperationName in ("Consent to application", "Add OAuth2PermissionGrant", "Add service principal")
| extend Actor = iff(isnotempty(tostring(InitiatedBy.user.userPrincipalName)),
                     tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName))
| where Actor !in~ (approved_admins)
| project TimeGenerated, OperationName, Actor, TargetResources, Result

// CUSTOM - Risky user followed by a credential or consent change inside 3 days
// The actor extraction mirrors Microsoft's own AuditLogs rules.
// ASSUMPTION: OperationName values. Pin exact strings first:
//   AuditLogs | where TimeGenerated > ago(30d)
//   | where OperationName has "consent" or OperationName has "method" or OperationName has "credential"
//   | distinct OperationName
let risky = AADRiskyUsers
    | where TimeGenerated > ago(3d)
    | where RiskLevel in ("medium", "high") and RiskState == "atRisk"
    | summarize RiskSeen = max(TimeGenerated) by UserPrincipalName = tolower(UserPrincipalName);
AuditLogs
| where TimeGenerated > ago(3d)
| extend Actor = iff(isnotempty(tostring(InitiatedBy.user.userPrincipalName)),
                     tostring(InitiatedBy.user.userPrincipalName), tostring(InitiatedBy.app.displayName))
| extend UserPrincipalName = tolower(Actor)
| join kind=inner risky on UserPrincipalName
| where TimeGenerated > RiskSeen
| where OperationName has_any ("consent", "method", "credential", "role")
| project TimeGenerated, OperationName, Actor, RiskSeen, TargetResources

// CUSTOM - Leaked credentials detection with no remediation after 24 hours
// ASSUMPTION: RiskEventType stores the Graph riskEventType string, leakedCredentials.
// The catalogue documents the value for the Graph API. Verify against a sample row.
AADUserRiskEvents
| where TimeGenerated > ago(7d)
| where RiskEventType == "leakedCredentials"
| summarize FirstSeen = min(TimeGenerated), LatestState = arg_max(TimeGenerated, RiskState)
            by UserPrincipalName, UserId
| where LatestState == "atRisk" and FirstSeen < ago(24h)
| project FirstSeen, UserPrincipalName, UserId

// CUSTOM - Detects creation of a user-managed GCP service account key (common persistence path)
// ASSUMPTION: GCPAuditLogs populates MethodName and PrincipalEmail per the standard table schema.
GCPAuditLogs
| where TimeGenerated > ago(1h)
| where MethodName == "google.iam.admin.v1.CreateServiceAccountKey"
| project TimeGenerated, ProjectId, PrincipalEmail, CallerIp, ResourceName, MethodName

// CUSTOM - Surfaces HIGH and CRITICAL Security Command Center findings as Sentinel alerts
// ASSUMPTION: GoogleCloudSCC populates FindingSeverity, FindingCategory and ResourceName.
// Confirm exact column casing with "GoogleCloudSCC | take 5" before enabling.
GoogleCloudSCC
| where TimeGenerated > ago(1h)
| where FindingSeverity in~ ("HIGH", "CRITICAL")
| project TimeGenerated, FindingSeverity, FindingCategory, ResourceName, State

// HUNT - Events MDCA enrichment flagged as uncommon for the user
// ASSUMPTION: per the schema doc, low-value events have an empty value and clean
// high-value events have an empty list, so this filter keeps only genuine anomalies.
CloudAppEvents
| where TimeGenerated > ago(1d)
| where isnotempty(UncommonForUser) and tostring(UncommonForUser) != "[]"
| project TimeGenerated, AccountDisplayName, Application, ActionType, ObjectName, UncommonForUser
| take 100

// Which watchlists have not been touched in 30 days?
// ASSUMPTION: lists expected to change more often, like leavers, deserve a shorter window.
Watchlist
| where TimeGenerated > ago(60d)
| summarize Items = count(), LastUpdate = max(LastUpdatedTimeUTC) by WatchlistAlias
| where LastUpdate < ago(30d)

// 04. Daily billable GB trend over 30 days with anomaly detection
// Run in: Defender portal > Advanced hunting (with Sentinel workspace selected) or Log Analytics Logs.
// Flags sudden ingestion spikes caused by runaway diagnostic settings, misconfigured DCRs or attack floods.
let start = startofday(ago(31d));
let end = startofday(now());
Usage
| where StartTime >= start and EndTime < end
| where IsBillable == true
| make-series DailyGB = round(sum(Quantity) / 1000.0, 2) default=0 on StartTime from start to end step 1d
| extend (Anomalies, Score, Baseline) = series_decompose_anomalies(DailyGB, 1.5, -1, 'linefit')
| mv-expand StartTime to typeof(datetime), DailyGB to typeof(real), Baseline to typeof(real), Anomalies to typeof(real), Score to typeof(real)
| project Day = format_datetime(StartTime, "yyyy-MM-dd"), DailyGB, BaselineGB = round(Baseline, 2), AnomalyFlag = Anomalies, Score = round(Score, 2)
| order by Day desc
